from pathlib import Path
import subprocess,json,statistics,random,hashlib
p=Path(__file__).parent;old=Path('/tmp/sirkit_rh_lcp_strategy_20261023/api.cpp');h=old.read_text();(p/'api.cpp').write_text(h)
variants={'baseline':p.parent/'baseline.hpp','fused':p/'compare_fused.hpp','reuse':p/'compare_reuse.hpp'};configs={'gcc_native':['/usr/bin/g++','-march=native'],'clang_standard':['/usr/bin/clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'],'gcc_fallback':['/usr/bin/g++','-U__SIZEOF_INT128__','-DSIRKIT_FORCE_STANDARD_ARITHMETIC','-DSIRKIT_DISABLE_SIMD']};rng=random.Random(715261);rows=[];builds=[]
for conf,cc in configs.items():
 for v,source in variants.items():
  exe=p/f'{conf}_{v}';cmd=['taskset','-c','0',*cc,'-std=c++23','-O2',f'-DSOURCE="{source}"','-DOP=1',str(p/'api.cpp'),'-o',str(exe)];o=subprocess.run(cmd,capture_output=True,text=True);assert o.returncode==0,o.stderr;builds.append(dict(configuration=conf,variant=v,cmd=cmd,source_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),stderr=o.stderr))
 print(conf,'compiled',flush=True)
 for n in [31,4097,1048576]:
  for pat in [0,1,2,3,4,8,9]:
   vals={v:[]for v in variants};checks={v:[]for v in variants}
   for rep in range(7):
    order=list(variants);rng.shuffle(order)
    for v in order:
     o=subprocess.run(['taskset','-c','4',str(p/f'{conf}_{v}'),str(n),str(pat),'32768'],capture_output=True,text=True);assert o.returncode==0,o.stderr;ns,checksum=o.stdout.split();vals[v].append(float(ns));checks[v].append(checksum)
    assert len({checks[v][-1]for v in variants})==1,(conf,n,pat,checks)
   med={v:statistics.median(x)for v,x in vals.items()};row=dict(configuration=conf,n=n,pattern=pat,raw=vals,median_ns=med,ratio={v:x/med['baseline']for v,x in med.items()});rows.append(row);(p/'results.json').write_text(json.dumps(dict(builds=builds,rows=rows),indent=2));print(conf,n,pat,{v:round(x,3)for v,x in row['ratio'].items()},flush=True)

