#define SKIP_RUNTIME_CHECKS
#include SOURCE
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <string>
#include <vector>
struct Query {std::size_t l,ol,n;};
template<class T> [[gnu::noinline]] static std::uint64_t run(const T&a,const T&b,const std::vector<Query>&qs){std::uint64_t sum=0;for(const auto&q:qs)sum+=a.equal(q.l,q.l+q.n,b,q.ol,q.ol+q.n);return sum;}
int main(int argc,char**argv){if(argc!=3)return 1;std::size_t n=std::strtoull(argv[1],nullptr,10);int mode=std::atoi(argv[2]);std::mt19937_64 rng(731904);std::string s(n,'a'),t(n,'a');for(char&c:s)c=static_cast<char>(rng());t=s;if(mode==2)t[n-1]^=1;if(mode==3)for(char&c:t)c=static_cast<char>(rng());RollingHash a(s,1000000007),b(t,1000000007);std::vector<Query>qs(32768);for(auto&q:qs){q.l=rng()%n;q.ol=mode==0?rng()%n:q.l;std::size_t max=std::min(n-q.l,n-q.ol);q.n=mode==2?max:rng()%(max+1);}std::uint64_t sum=run(a,b,qs);auto begin=std::chrono::steady_clock::now();for(int i=0;i<8;++i){sum+=run(a,b,qs);std::atomic_signal_fence(std::memory_order_seq_cst);}auto end=std::chrono::steady_clock::now();std::printf("%jd %ju\n",static_cast<std::intmax_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count()),static_cast<std::uintmax_t>(sum));}

