from pathlib import Path
import subprocess,json,hashlib
p=Path(__file__).parent;old=(p.parent/'baseline.hpp').read_text();submission=(p.parent/'submission.cpp').read_text();assert submission.count(old)==1
configs={'gcc_native':['/usr/bin/g++','-march=native','-DEVAL','-DONLINE_JUDGE'],'clang_standard':['/usr/bin/clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'],'gcc_fallback':['/usr/bin/g++','-U__SIZEOF_INT128__','-DSIRKIT_FORCE_STANDARD_ARITHMETIC','-DSIRKIT_DISABLE_SIMD']};rows=[]
for conf,cc in configs.items():
 hs={}
 for v,header in [('baseline',p.parent/'baseline.hpp'),('combined',p/'combined_fused.hpp')]:
  src=p/f'identity_{conf}_{v}.cpp';src.write_text(submission.replace(old,header.read_text(),1));exe=src.with_suffix('');cmd=['taskset','-c','0',*cc,'-std=c++23','-O2',str(src),'-o',str(exe)];o=subprocess.run(cmd,capture_output=True,text=True);assert o.returncode==0,o.stderr;section=exe.with_suffix('.text');subprocess.run(['objcopy','--dump-section','.text='+str(section),str(exe)],check=True);hs[v]=hashlib.sha256(section.read_bytes()).hexdigest()
 assert hs['baseline']==hs['combined'],(conf,hs);rows.append(dict(configuration=conf,text_sha256=hs,equal=True));print(conf,'text IDENTICAL',flush=True)
(p/'main-identity.json').write_text(json.dumps(rows,indent=2))
